fn resolve_redirect(base: &str, loc: &str) -> String {
    if loc.starts_with("https://") {
        loc.to_string()
    } else if loc.starts_with('/') {
        let host = base
            .strip_prefix("https://")
            .and_then(|r| r.split('/').next())
            .unwrap_or("huggingface.co");
        format!("https://{host}{loc}")
    } else {
        loc.to_string()
    }
}

